      "path": "src/index.ts",
      "content": "/**\n * Subagent run monitor, node half: a host-plane observer over subagent\n * lifecycle events plus the polling endpoint the browser panel reads.\n * The browser half ships via exports[\"./client\"], discovered through the\n * package.json \"dsh.client\" declaration.\n *\n * Process-wide events are attributed to their DIRECT parent session, so the\n * panel serves exactly ONE layer: the subagents the viewed session delegated\n * itself, never its grandchildren. A grandchild is reached by opening its own\n * parent's session, where it is again a direct child. Durable catalog facts\n * (label, mode) come from 'listChildren'.\n *\n * Usage/context/cache accounting is folded from each child's own session log:\n * 'assistant/message' (and 'assistant/chunk' usage) events carry a provider\n * TokenUsage (inputTokens/outputTokens/cacheReadTokens/cacheWriteTokens).\n * Live children serve their in-memory events; cold (persistence-only) children\n * are inspected once via 'sessionPersistence' and cached. The fold mirrors\n * @deepseek-ai/dsh-token-meter's tokenUsage + contextPressure projections\n * without depending on that package, so an out-of-repo plugin stays\n * self-contained.\n */\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { SessionEvent, SessionId } from '@deepseek-ai/dsh-session'\nimport type { SubagentRunEndInfo, SubagentRunInfo } from '@deepseek-ai/dsh-subagent'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\n\n/** One observed run, scalar-only so the wire copy stays lossless JSON. */\ninterface RunRow {\n  readonly runId: string\n  readonly id: string\n  readonly provider?: string\n  readonly local: boolean\n  /** Durable direct parent: the session that delegated this run. */\n  readonly parentId: string\n  readonly startedAt: number\n  status: string\n  endedAt?: number\n}\n\n/** Provider-neutral token accounting folded from one child's session log. */\ninterface UsageData {\n  /** Uncached prompt tokens (provider inputTokens). */\n  inputTokens: number\n  /** Generated completion tokens. */\n  outputTokens: number\n  /** Prompt tokens served from cache (cache hit). */\n  cacheReadTokens: number\n  /** Prompt tokens written into cache. */\n  cacheWriteTokens: number\n  /** Accumulated prompt-side context: input + cache read + cache write. */\n  contextTokens: number\n  /** Heuristic tokens of the session's tool outputs (tool/result content). */\n  toolOutputTokens: number\n  /** Advertised model context window, when 'request/context' logged one. */\n  contextWindow?: number\n  /** Prompt-side pressure of the newest usage sample, when reported. */\n  pressureTokens?: number\n  /**\n   * What the next request's prompt would cost: the newest sample plus the\n   * heuristic surface movement since (a compaction shadow shrinks it the\n   * moment content is replaced). This is the current-context occupancy figure;\n   * unlike {@link contextTokens} it is not cumulative over the session.\n   */\n  projectedTokens?: number\n}\n\n/** A panel row: an event-driven row enriched with durable catalog facts. */\ninterface PanelRow {\n  id: string\n  label?: string\n  mode?: string\n  parentId?: string\n  runId?: string\n  provider?: string\n  local?: boolean\n  startedAt?: number\n  endedAt?: number\n  status: string\n  /** Newest-first key for catalog rows without an observed start time. */\n  sortKey?: number\n  /** Folded token accounting for this child, when the log reports any. */\n  usage?: UsageData\n}\n\nconst MAX_PER_PARENT = 200\n\nexport const inject = ['sessions', 'subagents', 'webServer']\n\n/** Structural slice of the provider usage record carried by session events. */\ninterface TokenUsageLike {\n  inputTokens: number\n  outputTokens: number\n  cacheReadTokens?: number\n  cacheWriteTokens?: number\n}\n\n/** Disjoint usage buckets, matching the token-meter projection's totals. */\ninterface UsageBuckets {\n  uncachedInputTokens: number\n  outputTokens: number\n  cacheReadTokens: number\n  cacheWriteTokens: number\n}\n\n/** Shadow price armed by a compaction event, consumed by the next surface replace. */\ninterface ShadowPriceClaim {\n  start: number\n  end: number\n  tokens: number\n}\n\n/** Incremental fold state for one child session (watermark + last sample). */\ninterface UsageFoldState {\n  consumedEvents: number\n  totals: UsageBuckets\n  /** Cumulative heuristic tokens of tool/result content in this session. */\n  toolOutputTokens: number\n  last: { turn: number, step: number, buckets: UsageBuckets } | null\n  contextWindow?: number\n  pressureTokens?: number\n  /**\n   * Running heuristic price of the current model-visible surface (appends\n   * price each message; a compaction replacement subtracts its shadow price).\n   */\n  surfaceTokens: number\n  /** {@link surfaceTokens} at the newest usage sample, before that sample joined the surface. */\n  sampledSurfaceTokens?: number\n  /** Shadow price armed by a compaction event, consumed by the next replace. */\n  claim: ShadowPriceClaim | undefined\n}\n\n/** Minimal surface of the optional 'sessionPersistence' service we use. */\ninterface SessionPersistenceLike {\n  inspect(id: SessionId): Promise<{ meta: { id: SessionId, cwd?: string }, events: readonly SessionEvent[] }>\n}\n\nconst zeroBuckets = (): UsageBuckets => ({\n  uncachedInputTokens: 0,\n  outputTokens: 0,\n  cacheReadTokens: 0,\n  cacheWriteTokens: 0,\n})\n\nconst bucketsOf = (usage: TokenUsageLike): UsageBuckets => ({\n  uncachedInputTokens: usage.inputTokens,\n  outputTokens: usage.outputTokens,\n  cacheReadTokens: usage.cacheReadTokens ?? 0,\n  cacheWriteTokens: usage.cacheWriteTokens ?? 0,\n})\n\nconst bucketsEqual = (left: UsageBuckets, right: UsageBuckets): boolean =>\n  left.uncachedInputTokens === right.uncachedInputTokens\n  && left.outputTokens === right.outputTokens\n  && left.cacheReadTokens === right.cacheReadTokens\n  && left.cacheWriteTokens === right.cacheWriteTokens\n\n/** Replace one step's earlier sample instead of double counting it. */\nconst addReplacing = (\n  totals: UsageBuckets,\n  previous: UsageBuckets | undefined,\n  next: UsageBuckets,\n): UsageBuckets => ({\n  uncachedInputTokens: totals.uncachedInputTokens - (previous?.uncachedInputTokens ?? 0) + next.uncachedInputTokens,\n  outputTokens: totals.outputTokens - (previous?.outputTokens ?? 0) + next.outputTokens,\n  cacheReadTokens: totals.cacheReadTokens - (previous?.cacheReadTokens ?? 0) + next.cacheReadTokens,\n  cacheWriteTokens: totals.cacheWriteTokens - (previous?.cacheWriteTokens ?? 0) + next.cacheWriteTokens,\n})\n\n/** The usage a step reports, from a final message or an early usage chunk. */\nconst usageOf = (event: SessionEvent): TokenUsageLike | undefined => {\n  if (event.type === 'assistant/message') {\n    return (event.data as { usage?: TokenUsageLike }).usage\n  }\n  if (event.type === 'assistant/chunk') {\n    const chunk = event.data.chunk as { type: string, usage?: TokenUsageLike }\n    return chunk.type === 'usage' ? chunk.usage : undefined\n  }\n  return undefined\n}\n\nconst stepOf = (event: SessionEvent): { turn: number, step: number } =>\n  event.data as unknown as { turn: number, step: number }\n\n/** Fixed-density heuristic matching @deepseek-ai/dsh-token-meter's estimate. */\nconst CHARS_PER_TOKEN = 4\nconst BLOCK_OVERHEAD = 4\nconst ROLE_OVERHEAD = 4\n\n/**\n * Price a content-block list under the meter's fixed density (chars / 4 plus\n * per-block structural overhead). Tool outputs are not reported by providers,\n * so the context ring's \"tool output\" slice is this heuristic over\n * 'tool/result' message content — the same estimate the harness itself uses.\n */\nfunction estimateContentTokens(blocks: readonly unknown[]): number {\n  let tokens = 0\n  for (const block of blocks) {\n    const b = block as { type?: string; text?: string; content?: unknown[]; name?: string; arguments?: string }\n    switch (b.type) {\n      case 'text':\n      case 'reasoning':\n        tokens += Math.ceil((b.text ?? '').length / CHARS_PER_TOKEN) + BLOCK_OVERHEAD\n        break\n      case 'tool-result':\n        tokens += estimateContentTokens(b.content ?? []) + BLOCK_OVERHEAD\n        break\n      default:\n        tokens += BLOCK_OVERHEAD + Math.ceil(JSON.stringify(block).length / CHARS_PER_TOKEN)\n    }\n  }\n  return tokens\n}\n\n/**\n * The model-visible message an event derives to, mirroring the session\n * surface's projection rule: only 'user/message', 'assistant/message' (with\n * content) and 'tool/result' produce a priced message; everything else is\n * trace/replay data. The returned object is the message's content slice only.\n */\nconst surfaceMessageOf = (event: SessionEvent): { content: readonly unknown[] } | null => {\n  switch (event.type) {\n    case 'user/message': {\n      const data = event.data as { content?: readonly unknown[] }\n      return data.content !== undefined ? { content: data.content } : null\n    }\n    case 'assistant/message': {\n      const message = (event.data as { message?: { content?: readonly unknown[] } }).message\n      if (message === undefined || (message.content ?? []).length === 0) return null\n      return message as { content: readonly unknown[] }\n    }\n    case 'tool/result': {\n      const message = (event.data as { message?: { content?: readonly unknown[] } }).message\n      return message !== undefined ? (message as { content: readonly unknown[] }) : null\n    }\n    default:\n      return null\n  }\n}\n\n/**\n * Signed surface movement for one event plus the shadow-price claim to carry\n * forward — the same O(1) protocol the harness's surface projection uses. A\n * 'compaction/summary'/'compaction/prune' event arms a claim priced by its\n * logged shadowed token count; the immediately following surface replacement\n * consumes it and subtracts that price from the running surface total (so a\n * compaction visibly shrinks current occupancy). A replacement without an\n * armed claim folds with zero delta because the bounded state cannot\n * reconstruct the replaced range.\n */\nconst foldSurface = (\n  claim: ShadowPriceClaim | undefined,\n  event: SessionEvent,\n): { deltaTokens: number, claim: ShadowPriceClaim | undefined } => {\n  // 'compaction/summary'/'compaction/prune' live in the dsh-compaction event\n  // merge, absent from this plugin's static SessionEvent union — widen the\n  // type so the branch survives without a runtime narrowing to `never`.\n  const type = (event as { type?: string }).type\n  if (type === 'compaction/summary' || type === 'compaction/prune') {\n    const data = (event as { data?: {\n      shadowedRange?: { start?: number, end?: number }\n      shadowedTokenCount?: number\n    } }).data\n    const range = data?.shadowedRange\n    if (range !== undefined\n      && typeof range.start === 'number' && typeof range.end === 'number'\n      && typeof data?.shadowedTokenCount === 'number') {\n      return { deltaTokens: 0, claim: { start: range.start, end: range.end, tokens: data.shadowedTokenCount } }\n    }\n    return { deltaTokens: 0, claim: undefined }\n  }\n  const raw = event as SessionEvent & { surfaceOp?: unknown }\n  // Non-surface events move nothing and expire any armed claim.\n  if (raw.surfaceOp === undefined) return { deltaTokens: 0, claim: undefined }\n  const message = surfaceMessageOf(event)\n  const tokens = message === null ? 0 : estimateContentTokens(message.content) + ROLE_OVERHEAD\n  if (raw.surfaceOp === 'append') return { deltaTokens: tokens, claim: undefined }\n  const op = raw.surfaceOp as { op: string, start?: number, end?: number }\n  if (claim === undefined || op.start !== claim.start || op.end !== claim.end) {\n    return { deltaTokens: 0, claim: undefined }\n  }\n  return { deltaTokens: tokens - claim.tokens, claim: undefined }\n}\n\n/**\n * Fold new events into state from its watermark. Mirrors the token-meter's\n * tokenUsage + contextPressure projections: provider usage buckets are summed\n * with same-step replacement, 'request/context' supplies the context window,\n * the newest usage sample sets the prompt-side pressure, and 'tool/result'\n * content is priced heuristically into the tool-output bucket. The surface\n * fold (appends price each message, compaction replacements subtract their\n * shadow price) carries the sample forward so current occupancy\n * (`projectedTokens`) reacts the moment a compaction shadows a span. A usage\n * sample is stamped against the surface BEFORE the same event joins it, so it\n * anchors against the surface its own request saw.\n */\nfunction foldUsage(state: UsageFoldState, events: readonly SessionEvent[]): void {\n  let index = state.consumedEvents\n  for (; index < events.length; index++) {\n    const event = events[index]\n    if (event === undefined) continue\n    if (event.type === 'request/context') {\n      const contextWindow = (event.data as { contextWindow?: number }).contextWindow\n      if (contextWindow !== undefined) state.contextWindow = contextWindow\n      continue\n    }\n    if (event.type === 'tool/result') {\n      const message = (event.data as { message?: { content?: readonly unknown[] } }).message\n      if (message?.content !== undefined) state.toolOutputTokens += estimateContentTokens(message.content)\n    }\n    const usage = usageOf(event)\n    const fold = foldSurface(state.claim, event)\n    state.claim = fold.claim\n    if (usage !== undefined) {\n      const buckets = bucketsOf(usage)\n      const { turn, step } = stepOf(event)\n      const previous = state.last !== null && state.last.turn === turn && state.last.step === step\n        ? state.last.buckets\n        : undefined\n      if (previous === undefined || !bucketsEqual(previous, buckets)) {\n        state.totals = addReplacing(state.totals, previous, buckets)\n        state.last = { turn, step, buckets }\n        state.pressureTokens = buckets.uncachedInputTokens + buckets.cacheReadTokens + buckets.cacheWriteTokens\n        // Stamp the surface total before this event joins it.\n        state.sampledSurfaceTokens = state.surfaceTokens\n      }\n    }\n    if (fold.deltaTokens !== 0) state.surfaceTokens += fold.deltaTokens\n  }\n  state.consumedEvents = index\n}\n\nexport function apply(ctx: Context): void {\n  const runs = new Map<string, RunRow>()\n  const usageCache = new Map<string, UsageFoldState>()\n\n  const str = (value: unknown): string => typeof value === 'string' ? value : String(value)\n\n  const toUsageData = (state: UsageFoldState): UsageData | undefined => {\n    const { totals } = state\n    if (totals.uncachedInputTokens === 0 && totals.outputTokens === 0\n      && totals.cacheReadTokens === 0 && totals.cacheWriteTokens === 0) {\n      return undefined\n    }\n    const projectedTokens = state.pressureTokens !== undefined && state.sampledSurfaceTokens !== undefined\n      ? Math.max(0, state.pressureTokens + state.surfaceTokens - state.sampledSurfaceTokens)\n      : undefined\n    return {\n      inputTokens: totals.uncachedInputTokens,\n      outputTokens: totals.outputTokens,\n      cacheReadTokens: totals.cacheReadTokens,\n      cacheWriteTokens: totals.cacheWriteTokens,\n      contextTokens: totals.uncachedInputTokens + totals.cacheReadTokens + totals.cacheWriteTokens,\n      toolOutputTokens: state.toolOutputTokens,\n      ...(state.contextWindow !== undefined ? { contextWindow: state.contextWindow } : {}),\n      ...(state.pressureTokens !== undefined ? { pressureTokens: state.pressureTokens } : {}),\n      ...(projectedTokens !== undefined ? { projectedTokens } : {}),\n    }\n  }\n\n  // One hop up the durable lineage: the delegating session. The panel shows a\n  // single layer, so a run belongs to its direct parent and is never lifted to\n  // the root of the tree (that lifting is what made grandchildren surface in a\n  // parent's panel).\n  const parentOf = (childId: string): string | undefined => {\n    const child = ctx.sessions.get(childId as SessionId)\n    const parent = child?.header.parentSession\n    return parent === undefined ? undefined : str(parent)\n  }\n\n  const prune = (): void => {\n    const counts = new Map<string, number>()\n    for (const row of runs.values()) counts.set(row.parentId, (counts.get(row.parentId) ?? 0) + 1)\n    for (const [parentId, count] of counts) {\n      if (count <= MAX_PER_PARENT) continue\n      let excess = count - MAX_PER_PARENT\n      const rows = [...runs.values()]\n        .filter(row => row.parentId === parentId && row.status !== 'running')\n        .sort((a, b) => a.startedAt - b.startedAt)\n      for (const row of rows) {\n        if (excess <= 0) break\n        runs.delete(row.runId)\n        excess -= 1\n      }\n    }\n  }\n\n  const onStart = (info: SubagentRunInfo): void => {\n    const childId = str(info.id)\n    const parentId = parentOf(childId)\n    if (parentId === undefined) return\n    runs.set(str(info.runId), {\n      runId: str(info.runId),\n      id: childId,\n      provider: info.provider,\n      local: info.local,\n      parentId,\n      startedAt: Date.now(),\n      status: 'running',\n    })\n    prune()\n  }\n\n  const onEnd = (info: SubagentRunEndInfo): void => {\n    const row = runs.get(str(info.runId))\n    if (row === undefined) return\n    row.status = info.stopReason\n    row.endedAt = Date.now()\n  }\n\n  ctx.on('subagent/start', onStart, { global: true })\n  ctx.on('subagent/end', onEnd, { global: true })\n\n  /**\n   * Fold one child's usage. Live children serve their in-memory events\n   * incrementally; a cold child is inspected from persistence exactly once per\n   * process lifetime (the watermark cache then serves it). A missing optional\n   * 'sessionPersistence' or an unreadable log degrades to undefined.\n   */\n  const childUsage = async (childId: string): Promise<UsageData | undefined> => {\n    const live = ctx.sessions.get(childId as SessionId)\n    if (live !== undefined) {\n      let state = usageCache.get(childId)\n      if (state === undefined) {\n        state = { consumedEvents: 0, totals: zeroBuckets(), toolOutputTokens: 0, last: null, surfaceTokens: 0, claim: undefined }\n        usageCache.set(childId, state)\n      }\n      foldUsage(state, live.events)\n      return toUsageData(state)\n    }\n    const cached = usageCache.get(childId)\n    if (cached !== undefined) return toUsageData(cached)\n    const persistence = (ctx as unknown as { get(name: string): unknown }).get('sessionPersistence') as\n      SessionPersistenceLike | undefined\n    if (persistence === undefined) return undefined\n    try {\n      const inspected = await persistence.inspect(childId as SessionId)\n      const state: UsageFoldState = { consumedEvents: 0, totals: zeroBuckets(), toolOutputTokens: 0, last: null, surfaceTokens: 0, claim: undefined }\n      foldUsage(state, inspected.events)\n      usageCache.set(childId, state)\n      return toUsageData(state)\n    } catch {\n      return undefined\n    }\n  }\n\n  /** Attach usage to every row with a bounded concurrency (first load). */\n  const applyUsage = async (rows: PanelRow[]): Promise<void> => {\n    const limit = 8\n    let index = 0\n    const worker = async (): Promise<void> => {\n      while (index < rows.length) {\n        const i = index\n        index += 1\n        const row = rows[i]\n        if (row === undefined) continue\n        const usage = await childUsage(row.id)\n        if (usage !== undefined) row.usage = usage\n      }\n    }\n    await Promise.all(Array.from({ length: Math.min(limit, rows.length) }, worker))\n  }\n\n  // Merge event-driven rows with the durable DIRECT-child catalog (labels,\n  // mode). One layer only: 'listChildren' never enumerates grandchildren, so a\n  // parent's panel cannot fill up with a child's own delegations.\n  // Undefined values never reach the wire.\n  const enrich = async (sessionId: string): Promise<PanelRow[]> => {\n    let desc: Awaited<ReturnType<typeof ctx.subagents.listChildren>> = []\n    try {\n      desc = await ctx.subagents.listChildren(sessionId as SessionId)\n    } catch {\n      desc = []\n    }\n    const eventRows: RunRow[] = []\n    for (const row of runs.values()) {\n      if (row.parentId === sessionId) eventRows.push({ ...row })\n    }\n    eventRows.sort((a, b) => a.startedAt - b.startedAt)\n    const merged: PanelRow[] = []\n    const seen = new Set<string>()\n    // Catalog entries arrive oldest-first; the descending recency key lets\n    // unobserved rows rank newest-first below any observed run.\n    for (let index = 0; index < desc.length; index++) {\n      const entry = desc[index]\n      if (entry === undefined) continue\n      const id = str(entry.id)\n      seen.add(id)\n      // Every catalog entry here is a direct child of the queried session by\n      // construction, so the parent is the query itself (listChildren entries\n      // carry no parentId of their own).\n      const base = {\n        id,\n        ...(entry.kind === 'child' && entry.label !== undefined ? { label: entry.label } : {}),\n        ...(entry.kind === 'child' ? { mode: entry.mode } : {}),\n        parentId: sessionId,\n      }\n      const ev = eventRows.find(row => row.id === id)\n      if (ev !== undefined) {\n        merged.push({ ...base, ...ev })\n      } else {\n        merged.push({\n          ...base,\n          local: true,\n          sortKey: -(desc.length - index),\n          status: entry.kind === 'child' && entry.activity === 'running' ? 'running' : 'unknown',\n        })\n      }\n    }\n    for (const ev of eventRows) {\n      if (!seen.has(ev.id)) merged.push({ ...ev })\n    }\n    // Newest first: observed runs sort by start time; catalog-only rows fall\n    // back to their recency key (always below observed runs).\n    merged.sort((a, b) => {\n      const ka = a.startedAt ?? a.sortKey ?? Number.NEGATIVE_INFINITY\n      const kb = b.startedAt ?? b.sortKey ?? Number.NEGATIVE_INFINITY\n      return kb - ka\n    })\n    await applyUsage(merged)\n    return merged\n  }\n\n  ctx.effect(() => ctx.webServer.register({\n    kind: 'exact',\n    path: '/api/subagent-monitor/snapshot',\n    handler: async (req, res) => {\n      const url = new URL(req.url ?? '/', 'http://localhost')\n      const sessionId = url.searchParams.get('sessionId')\n      const payload = sessionId === null\n        ? { now: Date.now(), rows: [] }\n        : {\n            sessionId,\n            now: Date.now(),\n            rows: await enrich(sessionId),\n            // The viewed session's own usage/context (window, pressure,\n            // tool outputs) — the \"main session\" side of the dashboard.\n            main: await childUsage(sessionId),\n          }\n      res.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store' })\n      res.end(JSON.stringify(payload))\n    },\n  }), 'ui-subagent-monitor: snapshot route')\n}\n"
    },
    {
      "path": "src/client/index.ts",
      "content": "/**\n * Subagent run monitor, browser half entry: the plugin body only (no JSX —\n * tsdown pins the client bundle entry to src/client/index.ts). Components\n * live in ./panel.tsx.\n */\nimport type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'\nimport { Panel, Trigger, setLocale, setSessionsService, type MonitorSessionsService } from './panel'\n\nexport const inject = ['slots', 'sessions']\n\n/**\n * The host locale service, narrowed to the two reads the panel needs (same\n * loose-resolution reason as the sessions service below). `active` is the\n * host's UI language — the one Settings > General > Language writes.\n */\ninterface MonitorLocaleService {\n  getLocale(): { active: string }\n  subscribe(fn: () => void): () => void\n}\n\nexport function apply(ctx: ClientContext): void {\n  // The host-side dsh-session augmentation shadows the client sessions\n  // contract inside this dual-face package's program, so resolve the runtime\n  // service loosely and keep only the two methods the panel calls.\n  setSessionsService(ctx.get('sessions') as unknown as MonitorSessionsService | undefined)\n\n  // Follow the host UI language. 'locale' stays OUT of `inject` on purpose:\n  // a cordis inject is a hard requirement, and a composition without the\n  // locale plugin must still get the panel — it keeps the Chinese copy that\n  // has always shipped (see ./locales.ts). The nested inject fiber activates\n  // only while the service is there, and its unload restores the default.\n  ctx.inject(['locale'], (localeCtx: ClientContext) => {\n    localeCtx.effect(() => {\n      const locale = localeCtx.get('locale') as unknown as MonitorLocaleService | undefined\n      if (locale === undefined) return () => {}\n      const adopt = (): void => { setLocale(locale.getLocale().active) }\n      try {\n        adopt()\n        const unsubscribe = locale.subscribe(adopt)\n        return () => {\n          unsubscribe()\n          setLocale(undefined)\n        }\n      } catch {\n        // A locale service that does not answer these two reads leaves the\n        // panel on its default copy rather than taking the plugin down.\n        setLocale(undefined)\n        return () => {}\n      }\n    }, 'ui-subagent-monitor: host locale')\n  })\n\n  ctx.effect(() => {\n    const tag = document.createElement('style')\n    tag.dataset.plugin = '@leetoners/dsh-ui-subagent-monitor'\n    tag.textContent = `\n.smn-trigger {\n  display: inline-flex; align-items: center; gap: 6px;\n  border: 1px solid var(--dsw-alias-brand-primary, #2563eb);\n  background: var(--dsw-alias-brand-primary, #2563eb);\n  color: #ffffff;\n  border-radius: 8px; padding: 4px 10px; font-size: 12px;\n  line-height: 18px; cursor: pointer; font-weight: 500;\n  font-family: var(--dsw-font-family, inherit);\n}\n.smn-trigger:hover { filter: brightness(1.06); }\n.smn-trigger-label { font-size: 12px; }\n.smn-trigger-badge {\n  min-width: 16px; height: 16px; padding: 0 4px; border-radius: 999px;\n  background: #ffffff; color: var(--dsw-alias-brand-primary, #2563eb);\n  font-size: 10px; line-height: 16px; display: inline-flex;\n  align-items: center; justify-content: center; font-weight: 600;\n}\n.smn-panel {\n  pointer-events: auto;\n  position: fixed; width: 340px; max-height: min(560px, calc(100vh - 160px));\n  display: flex; flex-direction: column;\n  background: var(--dsw-specific-sidebar-fill, var(--dsw-alias-bg-base, #ffffff));\n  border: 1px solid var(--dsw-alias-border-l1, rgba(15, 23, 42, 0.08));\n  border-radius: 12px;\n  box-shadow: var(--dsw-shadow-lv3, 0 12px 32px rgba(15, 23, 42, 0.12));\n  font-family: var(--dsw-font-family, inherit);\n  font-size: 12px; overflow: hidden; z-index: 2147483000;\n}\n/* Move grip: a small handle sitting left of the panel title, only in the header. */\n.smn-grip-v {\n  flex: none; width: 18px; height: 20px; cursor: grab;\n  display: flex; align-items: center; justify-content: center;\n  border-radius: 4px;\n  user-select: none; -webkit-user-select: none; touch-action: none;\n}\n.smn-grip-v:hover { background: var(--dsw-alias-interactive-bg-hover, rgba(15, 23, 42, 0.05)); }\n.smn-grip-v:active { cursor: grabbing; }\n.smn-grip-v-icon {\n  flex: none; fill: currentColor;\n  color: var(--dsw-alias-label-tertiary, #cbd5e1); opacity: 0.55;\n}\n.smn-grip-v:hover .smn-grip-v-icon { color: var(--dsw-alias-label-primary, inherit); opacity: 1; }\n.smn-grip-h {\n  flex: none; height: 12px; cursor: ns-resize;\n  display: flex; align-items: center; justify-content: center;\n  user-select: none; -webkit-user-select: none; touch-action: none;\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(15, 23, 42, 0.06));\n}\n.smn-grip-h:hover { background: var(--dsw-alias-interactive-bg-hover, rgba(15, 23, 42, 0.05)); }\n.smn-grip-h-bar {\n  width: 32px; height: 4px; border-radius: 2px;\n  background: var(--dsw-alias-label-tertiary, #cbd5e1); opacity: 0.55;\n}\n.smn-grip-h:hover .smn-grip-h-bar { opacity: 1; }\n.smn-panel-header {\n  display: flex; align-items: center; gap: 8px; padding: 9px 12px;\n  user-select: none; background: transparent;\n  border-bottom: 1px solid var(--dsw-alias-border-l1, rgba(15, 23, 42, 0.06));\n}\n.smn-panel-title { font-weight: 600; font-size: 13px; line-height: 18px; color: var(--dsw-alias-label-primary, inherit); }\n.smn-panel-running { color: var(--dsw-alias-brand-primary, #2563eb); font-size: 12px; }\n.smn-panel-spacer { flex: 1; }\n.smn-rows {\n  overflow-y: auto; flex: 1;\n  display: flex; flex-direction: column; gap: 6px;\n  padding: 8px;\n  --dsh-scrollbar-thumb: var(--dsw-alias-scrollbar-bg-l2, rgba(15, 23, 42, 0.15));\n  --dsh-scrollbar-thumb-hover: var(--dsw-alias-scrollbar-hover-l2, rgba(15, 23, 42, 0.25));\n}\n/* Empty state: like .smn-rows it owns the flexible middle (flex: 1), so a\n   manually resized panel grows this region and the footer + height grip track\n   the bottom edge — instead of staying pinned near the top with dead space\n   left under the grip. */\n.smn-empty {\n  flex: 1;\n  /* Shrinkable floor: any height deficit is absorbed here (never by the\n     footer / height grip), so the grip always stays visible and draggable. */\n  min-height: 0;\n  overflow: hidden;\n  display: flex; align-items: center; justify-content: center;\n  padding: 24px 12px; text-align: center;\n  color: var(--dsw-alias-label-tertiary, #94a3b8);\n}\n.smn-row {\n  flex: none;\n  background: var(--dsw-alias-bg-layer-1, rgba(255, 255, 255, 0.6));\n  border: 1px solid var(--dsw-alias-border-l1, rgba(15, 23, 42, 0.07));\n  border-radius: 8px;\n  box-shadow: var(--dsw-shadow-lv1, 0 2px 4px rgba(15, 23, 42, 0.04));\n  /* One layer per panel: every card is a direct child, so there is no depth\n     indent to express. border-box keeps every card's outer edge identical\n     regardless of future padding changes. */\n  box-sizing: border-box;\n  padding: 7px 10px;\n}\n.smn-row-main { display: flex; align-items: center; justify-content: space-between; gap: 8px; }\n.smn-dot { width: 10px; height: 10px; flex: none; }\n/* Running: StateDot \"ongoing\" — pixel-art chase around the 3x3 outer ring\n   (DSH sidebar tab spec: 2x2 cells, clockwise stepped brightness trail). */\n.smn-dot-running { color: var(--dsw-static-deepseek-450, rgb(86, 134, 254)); }\n.smn-dot-cell { fill: currentColor; opacity: 0.15; animation: smn-dot-chase 1s infinite; }\n@keyframes smn-dot-chase {\n  0%, 12.4% { opacity: 1; }\n  12.5%, 24.9% { opacity: 0.6; }\n  25%, 37.4% { opacity: 0.35; }\n  37.5%, 100% { opacity: 0.15; }\n}\n/* Terminal states: StateDot spec — 10% same-color halo (::before) around a\n   6/10 solid core (::after); the color rides currentColor per state. */\n.smn-dot-ok, .smn-dot-error, .smn-dot-warn, .smn-dot-off {\n  position: relative; display: inline-block;\n}\n.smn-dot-ok::before, .smn-dot-error::before, .smn-dot-warn::before, .smn-dot-off::before {\n  content: ''; position: absolute; inset: 0; border-radius: 50%;\n  background: currentColor; opacity: 0.1;\n}\n.smn-dot-ok::after, .smn-dot-error::after, .smn-dot-warn::after, .smn-dot-off::after {\n  content: ''; position: absolute; inset: 20%; border-radius: 50%;\n  background: currentColor;\n}\n.smn-dot-ok { color: var(--dsw-alias-state-success-primary, rgb(34, 197, 94)); }\n.smn-dot-error { color: var(--dsw-alias-state-error-primary, rgb(236, 19, 19)); }\n.smn-dot-warn { color: var(--dsw-alias-state-warn-primary, rgb(245, 158, 11)); }\n.smn-dot-off { color: var(--dsw-alias-label-tertiary, #cbd5e1); }\n.smn-row-label {\n  flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  font-size: 13px; line-height: 18px;\n  color: var(--dsw-alias-label-primary, inherit);\n}\n.smn-row-foot {\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n  margin-top: 3px; padding-left: 18px;\n}\n.smn-row-time { color: var(--dsw-alias-label-tertiary, #94a3b8); font-variant-numeric: tabular-nums; flex: none; font-size: 11px; line-height: 16px; }\n.smn-row-meta {\n  flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  color: var(--dsw-alias-label-tertiary, #a3aec2); font-size: 11px; line-height: 16px;\n}\n.smn-row-open { flex: none; }\n/* Overall dashboard strip between the header and the card list: live counts\n   plus aggregate token usage / cache hit / context for the viewed layer, and\n   the donut (uncached input / cached input / output) with the hit rate at its\n   center. */\n.smn-summary {\n  flex: none;\n  display: flex; flex-direction: row; align-items: center; gap: 10px;\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--dsw-alias-border-l1, rgba(15, 23, 42, 0.06));\n  background: var(--dsw-alias-bg-layer-1, rgba(255, 255, 255, 0.35));\n}\n/* Status histogram on the summary's right: one vertical bar per state\n   (running / completed / failed) scaled to the largest count, with the count\n   and a short label underneath. Replaces the duplicated run/completed/failed\n   text cells — the footer still carries the textual status line. */\n.smn-chart {\n  flex: 1; min-width: 0; height: 56px;\n  display: flex; align-items: stretch; gap: 8px;\n}\n.smn-bar {\n  flex: 1; min-width: 0;\n  display: flex; flex-direction: column; align-items: center; gap: 2px;\n}\n.smn-bar-track {\n  flex: 1; width: 100%;\n  display: flex; align-items: flex-end; justify-content: center;\n  background: var(--dsw-alias-bg-layer-1, rgba(15, 23, 42, 0.05));\n  border-radius: 3px;\n}\n.smn-bar-fill { width: 12px; border-radius: 2px 2px 0 0; }\n.smn-bar-running { background: var(--dsw-alias-brand-primary, #2563eb); }\n.smn-bar-ok { background: var(--dsw-alias-state-success-primary, rgb(34, 197, 94)); }\n.smn-bar-err { background: var(--dsw-alias-state-error-primary, rgb(236, 19, 19)); }\n.smn-bar-count {\n  font-size: 11px; line-height: 13px; font-weight: 600;\n  font-variant-numeric: tabular-nums;\n  color: var(--dsw-alias-label-primary, inherit);\n}\n.smn-bar-label { font-size: 10px; line-height: 12px; color: var(--dsw-alias-label-tertiary, #94a3b8); }\n/* Donut: full background ring + three arcs (uncached input / cached input /\n   output), all in the deepseek blue scale (the harness's own brand blue);\n   the center text shows the cache-hit rate. */\n.smn-ring { flex: none; }\n.smn-ring-bg { stroke: var(--dsw-static-deepseek-100, rgb(228, 237, 253)); }\n.smn-ring-seg-uncached { stroke: var(--dsw-static-deepseek-200, rgb(211, 226, 255)); }\n.smn-ring-seg-cached { stroke: var(--dsw-static-deepseek-450, rgb(86, 134, 254)); }\n.smn-ring-seg-output { stroke: var(--dsw-static-deepseek-500, rgb(65, 118, 230)); }\n.smn-ring-pct {\n  fill: var(--dsw-static-deepseek-450, rgb(86, 134, 254));\n  font-size: 10px; font-weight: 600; font-variant-numeric: tabular-nums;\n}\n.smn-ring-label { fill: var(--dsw-static-deepseek-400, rgb(103, 158, 254)); font-size: 7px; }\n/* Ring cluster (left of the summary): context-window ring + two cache rings. */\n.smn-summary-left { display: flex; flex-direction: column; gap: 3px; align-items: flex-start; }\n.smn-summary-rings { display: flex; align-items: flex-end; gap: 8px; }\n.smn-ring-item { display: flex; flex-direction: column; align-items: center; gap: 2px; }\n.smn-ring-caption { font-size: 9px; line-height: 1; color: var(--dsw-alias-label-tertiary, #94a3b8); }\n.smn-ring-sm .smn-ring-pct { font-size: 8px; }\n.smn-ring-sm .smn-ring-label { font-size: 6px; }\n/* Context-window ring slices: input (blue-200) / tool output (amber) / output (blue-500). */\n.smn-ctx-seg-input { stroke: var(--dsw-static-deepseek-200, rgb(211, 226, 255)); }\n.smn-ctx-seg-tool { stroke: var(--dsw-static-amber-400, rgb(247, 173, 49)); }\n.smn-ctx-seg-output { stroke: var(--dsw-static-deepseek-500, rgb(65, 118, 230)); }\n.smn-legend-ctx-input { background: var(--dsw-static-deepseek-200, rgb(211, 226, 255)); }\n.smn-legend-ctx-tool { background: var(--dsw-static-amber-400, rgb(247, 173, 49)); }\n.smn-legend-ctx-output { background: var(--dsw-static-deepseek-500, rgb(65, 118, 230)); }\n/* Compact legend under the number rows, shown only while usage data exists. */\n.smn-summary-legend {\n  display: flex; flex-wrap: wrap; gap: 4px 10px;\n  padding-top: 1px;\n}\n.smn-legend-item {\n  display: inline-flex; align-items: center; gap: 4px;\n  font-size: 10px; line-height: 14px; color: var(--dsw-alias-label-tertiary, #94a3b8);\n}\n.smn-legend-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; }\n.smn-legend-uncached { background: var(--dsw-static-deepseek-200, rgb(211, 226, 255)); }\n.smn-legend-cached { background: var(--dsw-static-deepseek-450, rgb(86, 134, 254)); }\n.smn-legend-output { background: var(--dsw-static-deepseek-500, rgb(65, 118, 230)); }\n/* Per-card token line under the meta row. */\n.smn-row-usage {\n  display: flex; flex-wrap: wrap; gap: 3px 10px;\n  margin-top: 3px; padding-left: 18px;\n  color: var(--dsw-alias-label-tertiary, #94a3b8);\n  font-size: 10px; line-height: 15px; font-variant-numeric: tabular-nums;\n}\n.smn-panel-footer {\n  display: flex; align-items: center; gap: 8px; padding: 7px 10px;\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(15, 23, 42, 0.06));\n  background: transparent;\n}\n.smn-panel-stats { color: var(--dsw-alias-label-tertiary, #94a3b8); font-size: 11px; }\n.smn-btn {\n  border: 1px solid var(--dsw-alias-border-l1, rgba(15, 23, 42, 0.12));\n  background: transparent; color: var(--dsw-alias-label-primary, inherit);\n  border-radius: 6px; padding: 1px 8px; font-size: 11px; line-height: 16px;\n  cursor: pointer; font-family: inherit;\n}\n.smn-btn:hover {\n  border-color: var(--dsw-alias-border-l2, rgba(15, 23, 42, 0.3));\n  background: var(--dsw-alias-interactive-bg-hover, rgba(15, 23, 42, 0.04));\n}\n.smn-back { color: var(--dsw-alias-brand-primary, #2563eb); border-color: var(--dsw-alias-brand-primary, #2563eb); }\n/* ---- horizontal collapse: the panel folds left into a narrow strip ----\n   The width shrinks while the right edge stays anchored (the panel is\n   right-anchored by default; a dragged panel gets its explicit left shifted by\n   the same delta in toggleNarrow), so the box visibly folds toward the left.\n   What survives: the context + main-session rings at full size, restacked\n   top-to-bottom, and the subagent card list underneath in compact form.\n   NARROW_WIDTH in panel.tsx mirrors this width — change both together. */\n.smn-panel--narrow { width: 120px; }\n.smn-panel--narrow .smn-panel-header { gap: 2px; padding: 8px 6px; }\n.smn-panel--narrow .smn-grip-v { width: 14px; }\n/* Icon-only control: the narrow header has no room for a text label. */\n.smn-icon-btn { flex: none; width: 20px; padding: 1px 0; text-align: center; }\n.smn-panel--narrow .smn-panel-running { font-size: 11px; font-weight: 600; }\n.smn-panel--narrow .smn-summary { padding: 8px 6px; }\n/* Row -> column: the whole point of the narrow layout. */\n.smn-panel--narrow .smn-summary-left { width: 100%; }\n.smn-panel--narrow .smn-summary-rings {\n  flex-direction: column; align-items: center; gap: 10px; width: 100%;\n}\n.smn-panel--narrow .smn-rows { padding: 6px; gap: 5px; }\n.smn-panel--narrow .smn-empty { padding: 16px 8px; font-size: 11px; }\n/* Compact card: dot + label on one line, elapsed time right-aligned under it.\n   Rendered as a <button> when the child can be opened, so it needs the button\n   defaults reset back to the surrounding card look. */\n.smn-row-compact {\n  display: flex; flex-direction: column; align-items: stretch; gap: 2px;\n  width: 100%; padding: 6px 8px; text-align: left;\n  font: inherit; color: inherit;\n}\n.smn-row-compact .smn-row-main { gap: 6px; justify-content: flex-start; }\n.smn-row-compact .smn-row-label { font-size: 12px; line-height: 16px; }\n.smn-row-compact .smn-row-time { align-self: flex-end; font-size: 10px; }\n.smn-row-clickable { cursor: pointer; }\n.smn-row-clickable:hover {\n  border-color: var(--dsw-alias-border-l2, rgba(15, 23, 42, 0.3));\n  background: var(--dsw-alias-interactive-bg-hover, rgba(15, 23, 42, 0.04));\n}\n.smn-row-clickable:focus-visible {\n  outline: 2px solid var(--dsw-alias-brand-primary, #2563eb); outline-offset: 1px;\n}\n.smn-panel-footer--narrow { flex-wrap: wrap; gap: 4px; padding: 6px; }\n.smn-panel-footer--narrow .smn-panel-stats {\n  display: inline-flex; align-items: center; gap: 2px;\n  font-size: 11px; font-variant-numeric: tabular-nums;\n}\n.smn-stat-sep { color: var(--dsw-alias-label-tertiary, #cbd5e1); }\n.smn-stat-running { color: var(--dsw-alias-brand-primary, #2563eb); }\n.smn-stat-ok { color: var(--dsw-alias-state-success-primary, rgb(34, 197, 94)); }\n.smn-stat-err { color: var(--dsw-alias-state-error-primary, rgb(236, 19, 19)); }\n@media (max-width: 768px) {\n  .smn-panel { width: min(340px, calc(100vw - 24px)); }\n  /* The strip already fits every mobile viewport: keep it fixed so the ring\n     column never reflows on small screens. */\n  .smn-panel--narrow { width: 120px; }\n}\n`\n    document.head.appendChild(tag)